const crypto = require('crypto');

function b64uDecode(s) {
  s = s.replace(/-/g, '+').replace(/_/g, '/');
  while (s.length % 4) s += '=';
  return Buffer.from(s, 'base64').toString('utf8');
}

const item = $input.first().json;
const authHeader = item.headers?.authorization ?? '';
const token = authHeader.replace(/^Bearer\s+/i, '');
if (!token) throw new Error('401: Token eksik');

const parts = token.split('.');
if (parts.length !== 3) throw new Error('401: Geçersiz token');

const [header, payload, sig] = parts;
const expected = crypto
  .createHmac('sha256', $env.JWT_SECRET)
  .update(`${header}.${payload}`)
  .digest('base64')
  .replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');

const __sigBuf = Buffer.from(sig);
const __expBuf = Buffer.from(expected);
if (__sigBuf.length !== __expBuf.length || !crypto.timingSafeEqual(__sigBuf, __expBuf)) throw new Error('401: Geçersiz imza');

const claims = JSON.parse(b64uDecode(payload));
if (claims.exp < Math.floor(Date.now() / 1000)) throw new Error('401: Token süresi dolmuş');

const job_id = item.query?.job_id ?? '';
if (!job_id) throw new Error('400: job_id zorunlu');
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!UUID_RE.test(job_id)) throw new Error('400: job_id geçersiz format');

return [{ json: { job_id } }];

// Tüm draft satırlarını tek yanıtta topla
const job = $('Job Sorgula').first().json;
const draftItems = $('Drafts Çek').all();
const drafts = draftItems.map(i => i.json);
return [{ json: { ...job, drafts } }];
